import {seedProjects,services} from './project-data.js';
import {read,save,esc,toast} from './storage.js';
import {addPageSections} from './page-sections.js';
const page=document.body.dataset.page, app=document.querySelector('#app');
let projects=read('projects',seedProjects),categories=read('categories',['Branding','Logo Design','Packaging','Print & Editorial','Social Media','UI/UX','Advertising']);
const published=()=>projects.filter(p=>p.status==='Published');
const articles=()=>read('blog',[{id:1,title:'Why the best brands start with a question',category:'Branding',image:'assets/images/mono.svg',date:'2026-09-24',excerpt:'Before the logo, before the palette — find the question worth answering.'},{id:2,title:'Packaging that feels as good as it looks',category:'Process',image:'assets/images/bloom.svg',date:'2026-09-12',excerpt:'Material, form and feeling: making the everyday a little more considered.'},{id:3,title:'Finding your own visual voice',category:'Inspiration',image:'assets/images/offscript.svg',date:'2026-08-28',excerpt:'A few thoughts on curiosity, creative confidence and making work that matters.'},{id:4,title:'Building a useful brand guidelines document',category:'Branding',image:'assets/images/orbit.svg',date:'2026-08-10',excerpt:'Practical systems give a good identity room to grow.'}]);
const testimonials=()=>read('testimonials',[{id:1,name:'Alex Morgan',role:'Founder, MONO · fictional demo',quote:'A rare ability to take a feeling and turn it into something you can see. The new identity feels unmistakably us.'},{id:2,name:'Jamie Lee',role:'Creative lead, BLOOM · fictional demo',quote:'Every detail had a reason. From the first conversation to the final packaging, the process was thoughtful and collaborative.'},{id:3,name:'Sam Taylor',role:'Co-founder, ORBIT · fictional demo',quote:'Clear thinking, confident design, and a visual system that gave our next chapter a real sense of direction.'}]);
const profile=()=>read('profile',{name:'Studio Pixel',email:'hello@studiopixel.example',location:'Bengaluru, India · Working worldwide',available:true});
const link=(href,text,cls='text-link')=>`<a class="${cls}" href="${href}">${text} <span aria-hidden="true">↗</span></a>`;
const heading=(label,title,desc='')=>`<div class="page-heading wrap reveal"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>`;
const sectionTitle=(eyebrow,title,description='')=>`<div class="section-heading"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><p>${description}</p></div>`;
const navItems=[['index','Home'],['about','About'],['portfolio','Portfolio'],['services','Services'],['blog','Journal'],['contact','Contact']];
const header=()=>`${page==='index'?'<div class="announcement">A little strategy. A lot of imagination. Let’s make something great. <a href="start-project.html">Let’s talk ↗</a></div>':''}<header class="header"><div class="nav wrap"><a class="logo" href="index.html" aria-label="Studio Pixel home"><b aria-hidden="true">✳</b> STUDIO PIXEL<span class="accent">.</span></a><nav class="navlinks" id="navigation" aria-label="Main navigation">${navItems.map(([id,label])=>`<a ${page===id?'class="active" aria-current="page"':''} href="${id}.html">${label}</a>`).join('')}</nav>${link('start-project.html','Start a Project','button')}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Open navigation">☰</button></div></header>`;
const cta=()=>`<section class="cta"><div class="wrap"><div><div class="eyebrow">GOOD THINGS START WITH A CONVERSATION</div><h2>Have a good idea?<br>Let’s make it <span class="accent">unforgettable.</span></h2></div>${link('start-project.html','Let’s Work Together','button')}</div></section>`;
const footer=()=>`<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="logo" href="index.html"><b>✳</b> STUDIO PIXEL.</a><p>Independent thinking.<br>Distinctive design. Lasting impressions.</p><span class="badge">Illustrative portfolio / demo content</span></div><div><h4>Explore</h4>${navItems.slice(1).map(([p,t])=>`<a href="${p}.html">${t}</a>`).join('')}<a href="process.html">The Process</a><a href="case-studies.html">Case Studies</a><a href="testimonials.html">Kind Words</a></div><div><h4>What I Do</h4>${services.map((s,i)=>`<a href="service-details.html?id=${i}">${s}</a>`).join('')}<a href="portfolio.html">Portfolio Categories</a></div><div><h4>A little creative inspiration.</h4><p>Occasional notes on design, process and things worth sharing.</p><form class="newsletter"><label class="screen-reader" for="newsletter-email">Email address</label><input id="newsletter-email" type="email" name="email" placeholder="Your email address" required><button aria-label="Subscribe">↗</button></form><p>Demo subscription saved in this browser.</p><a href="contact.html#social">Social & contact details ↗</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Studio Pixel. Made with purpose.</span><div><a href="privacy-policy.html">Privacy Policy</a><a href="terms.html">Terms</a><a href="login.html">Demo Admin ↗</a></div></div></div></footer>`;
const card=p=>`<article class="project-card"><div class="project-image"><a href="project-details.html?id=${p.id}" aria-label="View ${esc(p.title)} project"><img src="${safeImage(p.image)}" alt="${esc(p.title)} — original ${esc(p.category)} concept presentation" loading="lazy"></a><button class="favorite ${read('favorites').includes(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="Save ${esc(p.title)}" aria-pressed="${read('favorites').includes(p.id)}">♡</button></div><a class="project-info" href="project-details.html?id=${p.id}"><div><h3>${esc(p.title)}</h3><p>${esc(p.category)} <span aria-hidden="true">/</span> ${esc(p.year)}</p></div><span class="arrow" aria-hidden="true">↗</span></a></article>`;
function safeImage(path){return /^assets\/images\/[\w.-]+\.svg$/.test(path)?path:'assets/images/mono.svg'}
const serviceCards=(full=false)=>`<div class="service-grid">${services.map((s,i)=>`<article class="service-card"><span class="service-icon" aria-hidden="true">${['✳','◎','◇','▤','✧','⌘'][i]}</span><h3>${s}</h3><p>${['Distinctive identities built on clear strategy. More than a logo — a whole world for your brand.','Simple, memorable marks that capture the character of your brand in a single idea.','Thoughtfully designed packaging that makes a connection, on the shelf and in your hands.','Considered layouts and expressive typography. Stories that deserve to be held.','A consistent, compelling visual presence that brings your brand into the conversation.','Intuitive digital experiences where purposeful design meets everyday usability.'][i]}</p>${full?'<p>Deliverables: strategy workshop, concept exploration, design development, final production files, usage guide.</p><p>Typical timeline: 3–6 weeks · Pricing tailored to scope.</p>':''}<div class="service-bottom"><span>0${i+1} / DESIGN SERVICE</span><a href="service-details.html?id=${i}" aria-label="Learn more about ${s}">Learn More ↗</a></div></article>`).join('')}</div>`;
const steps=()=>`<div class="steps">${['Discover','Define','Design','Deliver'].map((s,i)=>`<article class="step"><span>0${i+1} —</span><h3>${s}</h3><p>${['Good design begins with good questions. We explore your story, your audience and where you want to go.','Turn what we learn into a clear creative direction. A shared foundation for everything that follows.','Ideas take shape. We explore, refine and build a thoughtful visual system together.','Every file, every detail, ready for the real world. Plus the guidance to use it with confidence.'][i]}</p></article>`).join('')}</div>`;
const articleCard=a=>`<article class="article-card"><a href="blog-details.html?id=${a.id}"><img src="${safeImage(a.image)}" alt="${esc(a.category)} design study" loading="lazy"><small>${esc(a.category)} · ${esc(a.date)} · 4 min read</small><h3>${esc(a.title)} ↗</h3><p>${esc(a.excerpt)}</p></a></article>`;
function home(){return `<div class="wrap"><section class="hero reveal"><div><div class="eyebrow">INDEPENDENT GRAPHIC DESIGNER & ART DIRECTOR</div><h1>Design that makes<br>brands <span class="accent">impossible</span><br>to ignore.</h1><p class="intro">I build distinctive visual identities and digital experiences for ambitious brands that want to stand out, connect, and grow.</p><div class="actions">${link('portfolio.html','Explore My Work','button')}${link('contact.html','Let’s Collaborate','button secondary')}</div><div class="availability"><span class="dot"></span> Available for select projects <span>·</span> Based in India. Thinking worldwide.</div></div><div class="collage hero-visual" aria-label="Graphic design branding and packaging photography">               <img                 class="hero-photo"                 src="assets/images/hero-studio.png"                 alt="Cream and charcoal business cards, coral editorial artwork, an open branding book and skincare packaging on a sunlit studio table"                 width="1254"                 height="1254"                 fetchpriority="high"                 decoding="async"               />               <div class="seal">INDEPENDENT<br /><strong>✳</strong>BY DESIGN</div>               <div class="hero-caption"><span>BRANDING / PACKAGING / EDITORIAL</span><span>STUDIO PIXEL ↗</span></div>             </div></section></div><section class="brands"><div class="wrap"><span>A FEW FICTIONAL BRANDS<br>IN THIS DEMO</span><strong>NORTHLINE®</strong><strong>mono studio</strong><strong>FORM & CO.</strong><strong>◉ ORBITAL</strong><strong>COMMON GROUND</strong></div></section><section class="section wrap selected-work" id="selected-work" aria-label="Selected work">${sectionTitle('A SELECTION OF RECENT PROJECTS','Selected Work<span class="accent">.</span>','Different challenges. One considered approach. A little strategy, a lot of character.')}<div class="filters" id="home-filters" role="group" aria-label="Filter selected projects">${['All', 'Branding', 'Logo Design', 'Packaging', 'Print & Editorial', 'Advertising', 'UI/UX'].map((s,i)=>`<button class="chip ${i===0?'active':''}" data-home-filter="${s}" aria-pressed="${i===0}">${s}</button>`).join('')}</div><div class="project-grid" id="home-projects">${published().slice(0,6).map(card).join('')}</div><div class="work-footer"><p>Explore the ideas behind every project.</p>${link('portfolio.html','View All Projects')}</div></section><div class="marquee">IDEAS MADE VISIBLE <span>✳</span> BRANDS MADE MEMORABLE <span>✳</span> DESIGN WITH PURPOSE</div><section class="section wrap split"><div class="about-art"><img src="assets/images/offscript.svg" alt="An editorial design concept from the studio"><div class="about-tag">A curious mind.<br>A considered approach. ↗</div></div><div><div class="eyebrow">THE MIND BEHIND THE PIXELS</div><h2>Curiosity is my<br><span class="accent">creative process.</span></h2><p>I’m the independent designer behind Studio Pixel. I turn questions into ideas, and ideas into distinctive visual identities.</p><p>My approach brings strategic thinking and a hands-on love of craft together. Because the best design doesn’t just look good. It means something.</p>${link('about.html','A Little More About Me')}<div class="stats"><div><strong>06</strong><small>Concept projects</small></div><div><strong>06</strong><small>Creative disciplines</small></div><div><strong>01</strong><small>Independent perspective</small></div></div></div></section><section class="section tinted"><div class="wrap">${sectionTitle('WHAT I CAN HELP YOU WITH','Good design. Every touchpoint.','From your first impression to your next big chapter. Thoughtful design, built around you.')}${serviceCards()}</div></section><section class="section wrap">${sectionTitle('FROM THE FIRST QUESTION TO THE FINAL DETAIL','A clear path to better design.','Collaborative by nature. Considered at every step.')}${steps()}</section><section class="section featured"><div class="wrap">${sectionTitle('BEHIND THE DESIGN / FEATURED CASE STUDY','MONO. Less, but with more meaning.','A complete visual identity for a new perspective on architecture. Fictional concept project.')}<a href="project-details.html?id=1"><img src="assets/images/mono.svg" alt="MONO complete brand identity presentation" loading="lazy"></a><div class="actions">${link('project-details.html?id=1','Explore the Case Study','button')}</div></div></section><section class="section wrap"><div class="quote"><div class="eyebrow" style="justify-content:center">KIND WORDS / ILLUSTRATIVE TESTIMONIALS</div><div id="quote-content"></div><div class="slider-controls"><button class="icon-button" data-slide="-1" aria-label="Previous testimonial">←</button><button class="icon-button" data-slide="1" aria-label="Next testimonial">→</button></div></div></section><section class="section tinted"><div class="wrap">${sectionTitle('NOTES FROM THE STUDIO','The Creative Journal<span class="accent">.</span>','Thoughts on design, creative process and the things that spark an idea.')}<div class="journal-grid">${articles().slice(0,3).map(articleCard).join('')}</div><div class="center">${link('blog.html','More From the Journal')}</div></div></section>${cta()}`}
function portfolio(){return heading('THE PORTFOLIO','Selected Projects<span class="accent">.</span>','A collection of identities, experiences and ideas. Each with a different story. All designed with purpose.')+`<section class="wrap section" style="padding-top:0"><div class="filters" id="portfolio-filters">${['All',...categories,'Favorites'].map((s,i)=>`<button class="chip ${i===0?'active':''}" data-category="${esc(s)}">${esc(s)}</button>`).join('')}</div><div class="toolbar"><label class="screen-reader" for="search">Search projects</label><input type="search" id="search" placeholder="Search projects…"><select id="category" aria-label="Category"><option value="All">All categories</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="year" aria-label="Year"><option value="All">All years</option><option>2026</option><option>2025</option></select><select id="sort" aria-label="Sort projects"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="name">A–Z</option></select><button class="chip" id="reset">Reset</button></div><p class="results" aria-live="polite" id="results"></p><div class="project-grid" id="project-results"></div><div class="pagination" id="pagination"></div></section>${cta()}`}
function projectDetails(){const id=Number(new URLSearchParams(location.search).get('id')||1),p=published().find(p=>p.id===id);if(!p)return notFound();const all=published(),idx=all.findIndex(x=>x.id===id);return heading(`${esc(p.category)} / ${p.year}`,`${esc(p.title)}<span class="accent">.</span>`,esc(p.description))+`<div class="wrap"><div class="metadata"><div><small>CLIENT</small>${esc(p.title)} · fictional concept</div><div><small>SERVICES</small>${esc(p.category)}, Art Direction</div><div><small>YEAR</small>${p.year}</div><div><small>ROLE</small>Strategy & Design</div></div><div class="details-hero"><button class="gallery-open" data-image="${safeImage(p.image)}" style="border:0;padding:0;width:100%" aria-label="Open project image"><img src="${safeImage(p.image)}" alt="${esc(p.title)} project presentation"></button></div><div class="prose"><div class="eyebrow">THE CHALLENGE</div><h2>A distinct voice in a crowded world.</h2><p>${esc(p.title)} needed an identity that could communicate a clear point of view. The challenge was to move beyond familiar category conventions while remaining approachable, practical and true to the core idea.</p><h2>The idea. Made visible.</h2><p>We began with the essentials: a focused message, confident typography and a considered visual system. A small set of adaptable elements brings consistency across every application, from the first impression to the smallest detail.</p><h2>A palette with purpose.</h2><div class="swatches"><div style="background:#171717;color:#fff">#171717</div><div style="background:#f7f6f2">#F7F6F2</div><div style="background:#ff5a36;color:white">#FF5A36</div></div><h2 style="font-family:'Space Grotesk'">Aa. Space Grotesk</h2><p>Expressive headlines, paired with the clarity of DM Sans. A compact typographic system built to work across print and digital.</p></div><div class="gallery">${[p.image,...all.filter(x=>x.id!==id).slice(0,1).map(x=>x.image)].map((im,i)=>`<button class="gallery-open" data-image="${safeImage(im)}" aria-label="Open gallery image ${i+1}"><img src="${safeImage(im)}" alt="${i?'Complementary studio concept':'Project design detail'}" loading="lazy"></button>`).join('')}</div><div class="section-heading section">${link(`project-details.html?id=${all[(idx-1+all.length)%all.length].id}`,'Previous Project')}${link(`project-details.html?id=${all[(idx+1)%all.length].id}`,'Next Project')}</div><section class="section">${sectionTitle('KEEP EXPLORING','Related projects.')}<div class="project-grid">${all.filter(x=>x.id!==id).slice(0,2).map(card).join('')}</div></section></div><section class="cta"><div class="wrap"><h2>Let’s create your next chapter.</h2>${link('start-project.html?service='+encodeURIComponent(p.category),'Start a Similar Project','button')}</div></section>`}
function about(){return heading('INDEPENDENT BY DESIGN','A curious mind.<br>A considered approach<span class="accent">.</span>','Studio Pixel is an independent graphic design practice exploring the space where clear thinking meets expressive design.')+`<section class="section wrap split"><div class="about-art"><img src="assets/images/fieldwork.svg" alt="Digital design concept developed in the studio"><div class="about-tag">Always asking. Always making.</div></div><div><div class="eyebrow">HELLO, I’M STUDIO PIXEL</div><h2>Curiosity is my creative process.</h2><p>I believe great design starts with understanding. Who you are. What you stand for. And how you want people to feel.</p><p>This illustrative portfolio brings together concept identities, packaging and digital experiences. Every project is a chance to make something purposeful, distinctive and useful.</p>${link('resume.html','View / Download Resume')}</div></section><section class="section tinted"><div class="wrap split"><div><div class="eyebrow">THE PHILOSOPHY</div><h2>Thoughtful by nature.<br>Bold by choice.</h2><p>Ask better questions. Find the essential idea. Make every detail earn its place.</p><h3>Beyond the studio</h3><p>Independent magazines, architecture, long walks, thoughtful objects and the everyday details that spark a new idea.</p></div><div><h3>Experience & learning</h3><p class="note">Sample profile timeline — replace with your own experience and qualifications.</p><div class="timeline"><article><small>2024 — PRESENT / SAMPLE</small><h3>Independent Designer</h3><p>Brand strategy, identity systems and digital design.</p></article><article><small>2021 — 2024 / SAMPLE</small><h3>Visual Designer</h3><p>Collaborative brand, editorial and packaging projects.</p></article><article><small>EDUCATION / SAMPLE</small><h3>Communication Design</h3><p>Typography, visual storytelling and design research.</p></article></div></div></div></section><section class="section wrap">${sectionTitle('CRAFT & CAPABILITIES','A versatile creative toolkit.')}<div class="service-grid"><div class="service-card"><h3>Specializations</h3><p>Brand strategy · Visual identity · Art direction · Packaging · Editorial · UI/UX</p></div><div class="service-card"><h3>Tools & software</h3><p>Illustrator · Photoshop · InDesign · Figma · After Effects · Pen & paper</p></div><div class="service-card"><h3>Always learning</h3><p>Accessible design · Creative coding · Material exploration · Typography</p></div></div></section>${cta()}`}
function servicesPage(){return heading('THOUGHTFUL DESIGN, BUILT AROUND YOU','Make every<br>touchpoint count<span class="accent">.</span>','From a new identity to a complete digital experience. Focused creative services for brands ready for their next chapter.')+`<section class="section wrap" style="padding-top:15px">${serviceCards(true)}</section><section class="section tinted"><div class="wrap">${sectionTitle('THE WAY WE WORK','A collaborative process.')}${steps()}</div></section>${cta()}`}
function serviceDetails(){const i=Math.max(0,Math.min(5,Number(new URLSearchParams(location.search).get('id'))||0));return heading('DESIGN SERVICE / 0'+(i+1),services[i]+'<span class="accent">.</span>','Thoughtful strategy, a clear creative direction and considered design. Built around your brand, your audience and what comes next.')+`<section class="section wrap split"><img src="${seedProjects[i].image}" alt="${services[i]} concept"><div><h2>From a clear idea to a lasting impression.</h2><p>We start by understanding the business behind the brief. Together, we define a focused direction and explore design concepts before refining the details into a complete system.</p><h3>What’s included</h3><p>Discovery workshop · Research & positioning · Creative direction · Two initial concepts · Two refinement rounds · Production-ready files · Practical usage guide</p><p>Typical timeline: 3–6 weeks. Project pricing is tailored to your scope and deliverables.</p>${link('start-project.html?service='+encodeURIComponent(services[i]),'Inquire About This Service','button')}</div></section><section class="section tinted"><div class="wrap">${steps()}</div></section>${cta()}`}
function blog(){return heading('THOUGHTS, IDEAS & CREATIVE CURIOSITIES','The Creative Journal<span class="accent">.</span>','Notes on design, process and the things that make us look a little closer.')+`<section class="wrap section" style="padding-top:0"><div class="toolbar"><input id="blog-search" type="search" placeholder="Search the journal…" aria-label="Search articles"><select id="blog-category" aria-label="Article category"><option>All</option><option>Branding</option><option>Process</option><option>Inspiration</option></select></div><div id="featured-article"></div><p class="results" id="blog-results-count" aria-live="polite"></p><div class="journal-grid" id="blog-results"></div><div class="pagination" id="blog-pagination"></div></section>${cta()}`}
function article(){const a=articles().find(x=>x.id===Number(new URLSearchParams(location.search).get('id')||1));if(!a)return notFound();return heading(`${esc(a.category)} / ${esc(a.date)} / 4 MIN READ`,esc(a.title),esc(a.excerpt))+`<div class="wrap"><img src="${safeImage(a.image)}" alt="${esc(a.category)} cover artwork"><article class="prose"><p>Every design project begins long before the first shape is drawn. It starts with paying attention: to the people behind a brand, to the context around it, and to the small details that make it different.</p><h2>Start with understanding.</h2><p>Ask what the work needs to do. Who is it for? What should they understand, feel or remember? A clear answer is more useful than a long list of visual references. It gives the team something shared to return to when a project gets complicated.</p><h2>Make room for exploration.</h2><p>The first idea is a starting point. Sketch widely, test different directions and give unexpected connections a little space. Good creative work often comes from combining something familiar with a perspective we haven’t considered yet.</p><img src="assets/images/offscript.svg" alt="Explorations in editorial typography" loading="lazy"><h2>Refine with intention.</h2><p>Editing is part of designing. Remove the elements that don’t serve the idea. Test the system at different scales, in different contexts, and with real content. A design becomes stronger when every choice has a purpose.</p><h2>Leave room for the next chapter.</h2><p>A useful identity is a framework for the future. Build in enough consistency to feel recognizable, and enough flexibility to grow. The most memorable brands keep their character while finding new ways to express it.</p><p class="note">An original demonstration article for the Studio Pixel portfolio.</p></article><section class="section">${sectionTitle('KEEP READING','More from the journal.')}<div class="journal-grid">${articles().filter(x=>x.id!==a.id).slice(0,3).map(articleCard).join('')}</div></section></div>${cta()}`}
function inquiry(){const p=profile();return heading('LET’S MAKE SOMETHING MEANINGFUL',page==='contact'?'Good things start<br>with a conversation<span class="accent">.</span>':'Your next chapter<br>starts here<span class="accent">.</span>','Have a project in mind? Share a little about it below. Let’s see what we can create together.')+`<section class="section wrap contact-layout" style="padding-top:20px"><div><div class="availability" style="margin-top:0"><span class="dot"></span>${p.available?'Available for select projects':'Currently booking future projects'}</div><h3>Say hello.</h3><a href="mailto:${esc(p.email)}">${esc(p.email)}</a><h3>Based here. Working everywhere.</h3><p>${esc(p.location)}</p><h3 id="social">Stay connected.</h3><p>Social profiles are not configured in this demo. Add your handles in website settings.</p><p class="note">This is a frontend demonstration. Inquiries are saved only in this browser; no email is sent. The sample email address is not a live mailbox.</p></div><form id="inquiry-form" class="form-grid"><label class="field">Full Name *<input name="name" required minlength="2" maxlength="100" autocomplete="name"></label><label class="field">Email Address *<input name="email" required type="email" autocomplete="email"></label><label class="field">Company / Brand<input name="company" maxlength="120" autocomplete="organization"></label><label class="field">Service Required *<select name="service" required><option value="">Select a service</option>${services.map(s=>`<option ${new URLSearchParams(location.search).get('service')===s?'selected':''}>${s}</option>`).join('')}<option>Something else</option></select></label><label class="field">Project Budget *<select name="budget" required><option value="">Select budget</option><option>Under ₹50,000</option><option>₹50,000–₹1,00,000</option><option>₹1,00,000–₹3,00,000</option><option>₹3,00,000+</option><option>Let’s discuss</option></select></label><label class="field">Expected Timeline *<select name="timeline" required><option value="">Select timeline</option><option>Within a month</option><option>1–3 months</option><option>3–6 months</option><option>Flexible</option></select></label><label class="field full">Tell Me About Your Project *<textarea name="description" required minlength="20" maxlength="5000" placeholder="The idea, the challenge, the big picture…"></textarea></label><label class="field full">Reference Website (optional)<input name="reference" type="url" placeholder="https://" maxlength="500"></label><label class="consent full"><input name="consent" type="checkbox" required> <span>I agree to the <a href="privacy-policy.html" style="text-decoration:underline">Privacy Policy</a> and saving this demo inquiry in this browser.</span></label><div class="full"><button class="button" type="submit">Save Project Inquiry ↗</button><p class="form-note" id="inquiry-feedback" role="status">Your details stay on this device.</p></div></form></section>`}
function auth(){const register=page==='register',forgot=page==='forgot-password';return `<div class="auth-box"><div class="eyebrow">STUDIO PIXEL / DEMO ACCESS</div><h2>${forgot?'Reset your demo access.':register?'Create a demo profile.':'Back to the studio.'}</h2><p>Frontend demo only. This does not provide secure authentication. Do not use a real password.</p><form id="auth-form">${register?'<label class="field">Name<input name="name" required minlength="2"></label>':''}<label class="field">Email<input name="email" type="email" required></label>${!forgot?'<label class="field">Demo password<input name="password" type="password" required minlength="6" autocomplete="off"></label>':''}<button class="button">${forgot?'Reset Demo Session':register?'Create Demo Profile':'Enter Demo Dashboard'} ↗</button></form><p style="margin-top:20px">${forgot?'<a href="login.html">Back to login</a>':`<a href="${register?'login':'register'}.html">${register?'Already have a demo profile?':'Create a demo profile'}</a> · <a href="forgot-password.html">Reset access</a>`}</p><p>No real credentials are required. The login form opens a local demonstration session.</p></div>`}
function notFound(){return heading('404 / A LITTLE OFF THE GRID','This page took<br>a creative detour<span class="accent">.</span>','The project or page you’re looking for isn’t here.')+`<div class="wrap section">${link('index.html','Back to the Studio','button')}</div>`}
function simple(){if(page==='process')return heading('HOW WE GET THERE','Clarity at every step<span class="accent">.</span>','A collaborative process that leaves room for curiosity and keeps the work moving with purpose.')+`<section class="section wrap">${steps()}<div class="prose"><h2>Built on conversation.</h2><p>Each stage ends with a clear review. We agree the direction before moving forward, keep feedback focused and bring every decision back to your goals.</p><h2>What to expect</h2><p>A shared brief, regular progress updates, documented decisions and a careful handover. Timelines and revision rounds are agreed before a project begins.</p></div></section>${cta()}`;
if(page==='case-studies')return heading('THE THINKING BEHIND THE WORK','Ideas. In practice<span class="accent">.</span>','Explore the challenges, decisions and details behind these fictional studio projects.')+`<section class="section wrap"><div class="project-grid">${published().map(card).join('')}</div></section>${cta()}`;
if(page==='testimonials')return heading('KIND WORDS / DEMO CONTENT','Good work starts<br>with good people<span class="accent">.</span>','Illustrative testimonials for this demonstration portfolio; these are fictional client statements.')+`<section class="section wrap service-grid">${testimonials().map(t=>`<article class="service-card"><span class="accent">★★★★★</span><p>“${esc(t.quote)}”</p><h3>${esc(t.name)}</h3><p>${esc(t.role)}</p></article>`).join('')}</section>${cta()}`;
if(page==='resume')return heading('THE SHORT VERSION','Studio Pixel / Resume<span class="accent">.</span>','Illustrative designer profile. Replace this sample content with your actual experience before sharing.')+`<div class="wrap"><div class="actions"><button class="button" id="print-resume">Print / Save as PDF ↗</button>${link('contact.html','Get in Touch','button secondary')}</div><div class="prose"><h2>Independent Graphic Designer</h2><p>Brand identity, packaging, editorial design and digital experiences. A considered approach grounded in strategic thinking and visual craft.</p><h2>Experience — sample</h2><p>2024–Present / Independent Designer, Studio Pixel<br>2021–2024 / Visual Designer, Sample Studio</p><h2>Education — sample</h2><p>Communication Design · Typography, visual research and art direction.</p><h2>Selected skills</h2><p>Brand strategy · Identity systems · Art direction · Packaging · Editorial · UI/UX</p><h2>Tools</h2><p>Figma · Illustrator · Photoshop · InDesign · After Effects</p><h2>Contact</h2><p>${esc(profile().email)}<br>${esc(profile().location)}</p></div></div>`;
return heading('STUDIO PIXEL / '+(page==='terms'?'TERMS':'PRIVACY'),page==='terms'?'Terms of use.':'Your privacy matters.','Information about this demonstration portfolio and how browser data is used.')+`<article class="prose wrap"><h2>${page==='terms'?'Using this demo':'Data on this device'}</h2><p>This is an illustrative portfolio with fictional brands, sample project work and demonstration management tools. It does not provide paid services or secure account access.</p><h2>Local storage</h2><p>Project changes, inquiries, favorites, demo profile details and newsletter subscriptions are stored in your browser’s local storage. There is no backend email service or application database. Data is specific to this browser and origin.</p><h2>External resources</h2><p>Google Fonts is requested for typography. The hosting provider may process standard request information to serve the site. All project artwork is included locally.</p><h2>Managing your information</h2><p>You can remove demo inquiries from the admin area or clear this site’s data in your browser settings. Do not submit sensitive information or real passwords.</p><h2>Portfolio artwork</h2><p>The branding artwork was created for this demonstration. All clients and endorsements shown are fictional.</p><p>Updated October 15, 2026.</p></article>`}

const adminPages=['admin-dashboard','project-management','add-project','edit-project','category-management','inquiry-management','testimonial-management','blog-management','profile-settings','website-settings'];
const adminNav=[['admin-dashboard','Dashboard'],['project-management','Projects'],['category-management','Categories'],['inquiry-management','Inquiries'],['testimonial-management','Testimonials'],['blog-management','Blog'],['inquiry-management?view=messages','Messages'],['profile-settings','Profile'],['website-settings','Settings']];
function admin(){if(!read('session',null)){location.replace('login.html');return ''}let title=page.replaceAll('-',' ').replace(/\b\w/g,c=>c.toUpperCase());return `<div class="admin-layout"><aside class="admin-sidebar"><a class="logo" href="index.html"><b>✳</b> STUDIO PIXEL.</a><small>WORKSPACE / DEMO</small><nav aria-label="Dashboard">${adminNav.map(([p,t])=>`<a href="${p.split('?')[0]}.html${p.includes('?')?'?'+p.split('?')[1]:''}" class="${page===p?'active':''}">${t}</a>`).join('')}</nav><small>Local browser data only.</small><a href="index.html">↗ View Website</a><a href="#" id="logout">Log out</a></aside><main class="admin-main" id="main"><div class="admin-header"><div><p style="font-size:10px">STUDIO PIXEL / WORKSPACE</p><h1>${title}</h1></div>${link('add-project.html','+ Add Project','button')}</div><span class="badge">Frontend demonstration · not secure authorization</span><div id="admin-content">${adminContent()}</div></main></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}">Nothing here yet.</td></tr>`}</tbody></table></div>`}
function adminContent(){if(page==='admin-dashboard'){const inquiries=read('inquiries');return `<div class="admin-stats">${[['Total Projects',projects.length],['Published Projects',published().length],['Draft Projects',projects.filter(p=>p.status==='Draft').length],['Total Inquiries',inquiries.length]].map(([l,n])=>`<div class="admin-stat"><p>${l}</p><strong>${n}</strong><small class="accent">Browser demo data</small></div>`).join('')}</div><div class="panels"><section class="panel"><h3>Portfolio Views</h3><p style="font-size:11px;margin-bottom:15px">Illustrative chart · local page views: ${read('views',0)}</p><div class="chart">${[32,55,42,70,62,88,105].map((h,i)=>`<div style="height:${h}px"><span>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join('')}</div></section><section class="panel"><h3>Project Categories</h3>${categories.map(c=>`<p style="display:flex;justify-content:space-between;font-size:12px;margin:9px 0"><span>${esc(c)}</span><b>${projects.filter(p=>p.category===c).length}</b></p>`).join('')}</section></div><section class="panel"><h3>Recent Inquiries</h3>${inquiryTable(inquiries.slice(-5).reverse())}</section><section class="panel" style="margin-top:25px"><h3>Recent Activities</h3>${read('activity',['Workspace ready. Add a project or submit a demo inquiry to get started.']).slice(-6).reverse().map(s=>`<p style="font-size:12px;padding:8px 0;border-bottom:1px solid var(--line)">${esc(s)}</p>`).join('')}</section>`}
if(page==='project-management')return `<div class="toolbar"><input id="admin-search" type="search" placeholder="Search project table" aria-label="Search project table"></div>`+table(['PROJECT','CATEGORY','YEAR','STATUS','ACTIONS'],projects.map(p=>`<tr data-row><td>${esc(p.title)}</td><td>${esc(p.category)}</td><td>${p.year}</td><td><span class="badge">${esc(p.status)}</span></td><td><a href="edit-project.html?id=${p.id}">Edit ↗</a> <button data-toggle-project="${p.id}">${p.status==='Draft'?'Publish':'Unpublish'}</button><button data-delete="projects:${p.id}">Delete</button></td></tr>`));
if(page==='add-project'||page==='edit-project'){const p=projects.find(p=>p.id===Number(new URLSearchParams(location.search).get('id')))||{title:'',category:categories[0],year:2026,status:'Draft',description:'',image:'assets/images/mono.svg'};return `<form class="form-grid panel" id="project-form" data-id="${p.id||''}"><label class="field">Project title<input name="title" value="${esc(p.title)}" required maxlength="80"></label><label class="field">Category<select name="category">${categories.map(c=>`<option ${p.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field">Year<input name="year" type="number" min="2000" max="2100" value="${p.year}" required></label><label class="field">Status<select name="status"><option ${p.status==='Draft'?'selected':''}>Draft</option><option ${p.status==='Published'?'selected':''}>Published</option></select></label><label class="field full">Description<textarea name="description" required>${esc(p.description)}</textarea></label><label class="field full">Artwork<select name="image">${seedProjects.map(s=>`<option value="${s.image}" ${p.image===s.image?'selected':''}>${s.title} composition</option>`).join('')}</select></label><div class="full"><button class="button">Save Project ↗</button></div></form>`}
if(page==='inquiry-management')return `<section class="panel"><h3>${location.search?'Messages / Inquiries':'Project Inquiries'}</h3><p class="form-note">Only submissions from this browser appear here.</p>${inquiryTable(read('inquiries').slice().reverse())}</section>`;
if(page==='category-management')return `<form id="category-form" class="toolbar"><input name="name" required maxlength="50" placeholder="New category name" aria-label="Category name"><button class="button">Add Category</button></form>`+table(['CATEGORY','PROJECTS','ACTION'],categories.map((c,i)=>`<tr><td>${esc(c)}</td><td>${projects.filter(p=>p.category===c).length}</td><td><button data-category-edit="${i}">Rename</button><button data-category-delete="${i}">Delete</button></td></tr>`));
if(page==='testimonial-management')return `<button class="button" data-edit-record="testimonials:new">+ Add Testimonial</button><div style="margin-top:25px">${table(['NAME','QUOTE','ACTION'],testimonials().map(t=>`<tr><td>${esc(t.name)}</td><td style="white-space:normal;max-width:400px">${esc(t.quote)}</td><td><button data-edit-record="testimonials:${t.id}">Edit</button><button data-delete="testimonials:${t.id}">Delete</button></td></tr>`))}</div>`;
if(page==='blog-management')return `<button class="button" data-edit-record="blog:new">+ Add Article</button><div style="margin-top:25px">${table(['ARTICLE','CATEGORY','DATE','ACTION'],articles().map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.category)}</td><td>${esc(a.date)}</td><td><button data-edit-record="blog:${a.id}">Edit</button><button data-delete="blog:${a.id}">Delete</button></td></tr>`))}</div>`;
if(page==='profile-settings'){const p=profile();return `<form id="profile-form" class="form-grid panel"><label class="field">Studio name<input name="name" value="${esc(p.name)}" required></label><label class="field">Contact email<input name="email" type="email" value="${esc(p.email)}" required></label><label class="field full">Location<input name="location" value="${esc(p.location)}" required></label><label class="consent full"><input name="available" type="checkbox" ${p.available?'checked':''}>Available for projects</label><div class="full"><button class="button">Save Profile</button></div></form>`}
return `<form class="panel form-grid" id="settings-form"><label class="field full">Reading preference<select name="contrast"><option value="default">Default palette</option><option value="high" ${read('contrast')==='high'?'selected':''}>Higher text contrast</option></select></label><label class="field full">Social profile handles (plain text)<input name="social" value="${esc(read('social',''))}" placeholder="Instagram: @yourstudio, Behance: yourstudio"></label><div class="full"><button class="button">Save Preferences</button></div></form><p class="note">Preferences and content are saved to this browser only. No shared server data or real authentication is configured.</p>`}
function inquiryTable(items){return table(['NAME','SERVICE','STATUS','ACTION'],items.map(i=>`<tr><td>${esc(i.name)}<br><small>${esc(i.email)}</small></td><td>${esc(i.service)}</td><td>${esc(i.status||'New')}</td><td><button data-inquiry-view="${i.id}">View</button><button data-inquiry-status="${i.id}">Mark ${i.status==='Reviewed'?'New':'Reviewed'}</button><button data-delete="inquiries:${i.id}">Delete</button></td></tr>`))}

function render(){document.body.classList.toggle('high-contrast',read('contrast')==='high');if(adminPages.includes(page)){app.innerHTML=admin();return}let content=page==='index'?home():page==='portfolio'?portfolio():page==='project-details'?projectDetails():page==='about'?about():page==='services'?servicesPage():page==='service-details'?serviceDetails():page==='blog'?blog():page==='blog-details'?article():['contact','start-project'].includes(page)?inquiry():['login','register','forgot-password'].includes(page)?auth():page==='404'?notFound():simple();app.innerHTML=header()+`<main id="main">${content}</main>`+footer();if(read('social','')){const social=document.querySelector('#social+p');if(social)social.textContent=read('social','')}}
// Use the readable HTML in each page as the initial document. Only rebuild
// records that depend on a query parameter or this browser's demo data.
const recordPages=['project-details','service-details','blog-details'];
const localContentPages=['index','about','contact','start-project','case-studies','testimonials'];
const hasLocalContent=['projects','profile','social','testimonials'].some(key=>read(key,null)!==null);
const needsDynamicContent=adminPages.includes(page)
 || (recordPages.includes(page)&&location.search)
 || (localContentPages.includes(page)&&hasLocalContent);
document.body.classList.toggle('high-contrast',read('contrast')==='high');
if(!app.querySelector('#main')||needsDynamicContent)render();
if(!app.querySelector('.page-additions'))addPageSections(page);
save('views',read('views',0)+1);
document.addEventListener('storage-error',()=>toast('Storage is unavailable or full. Your changes were not saved.'));
function activity(message){save('activity',[...read('activity'),new Date().toLocaleString()+': '+message].slice(-50))}
function modal(html){const d=document.querySelector('#modal');d.innerHTML=`<button class="close" aria-label="Close dialog">×</button>${html}`;d.showModal();return d}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;
if(b.matches('.menu-toggle')){const open=document.querySelector('.navlinks').classList.toggle('open');b.setAttribute('aria-expanded',open);b.setAttribute('aria-label',open?'Close navigation':'Open navigation')}
if(b.matches('.back-top'))window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
if(b.matches('.close'))document.querySelector('#modal').close();
if(b.matches('[data-favorite]')){const id=Number(b.dataset.favorite),fav=read('favorites'),saved=fav.includes(id);if(save('favorites',saved?fav.filter(n=>n!==id):[...fav,id])){b.classList.toggle('saved',!saved);b.setAttribute('aria-pressed',!saved);toast(saved?'Removed from favorites':'Project saved to favorites')}}
if(b.matches('[data-home-filter]')){document.querySelectorAll('[data-home-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelector('#home-projects').innerHTML=published().filter(p=>b.dataset.homeFilter==='All'||p.category===b.dataset.homeFilter).map(card).join('')||'<p class="empty">No projects in this category.</p>'}
if(b.id==='logout'){e.preventDefault();save('session',null);location.href='login.html'}
if(b.id==='print-resume')window.print();
if(b.matches('[data-delete]')){e.preventDefault();const [key,id]=b.dataset.delete.split(':');modal(`<h3>Delete this ${key==='projects'?'project':'record'}?</h3><p style="margin:20px 0">This removes the record from this browser’s demo data.</p><button class="button" id="confirm-delete">Delete</button>`);document.querySelector('#confirm-delete').onclick=()=>{const list=key==='projects'?projects:key==='testimonials'?testimonials():key==='blog'?articles():read(key);if(save(key,list.filter(x=>x.id!==Number(id)))){activity('Deleted '+key+' record');location.reload()}}}
if(b.matches('[data-toggle-project]')){projects=projects.map(p=>p.id===Number(b.dataset.toggleProject)?{...p,status:p.status==='Published'?'Draft':'Published'}:p);if(save('projects',projects)){activity('Updated project publication status');location.reload()}}
if(b.matches('[data-inquiry-status]')){const id=Number(b.dataset.inquiryStatus);if(save('inquiries',read('inquiries').map(i=>i.id===id?{...i,status:i.status==='Reviewed'?'New':'Reviewed'}:i)))location.reload()}
if(b.matches('[data-inquiry-view]')){const i=read('inquiries').find(i=>i.id===Number(b.dataset.inquiryView));modal(`<h3>${esc(i.name)}</h3><p>${esc(i.email)} · ${esc(i.company)}</p><div class="prose"><p>${esc(i.description)}</p><p>Service: ${esc(i.service)}<br>Budget: ${esc(i.budget)}<br>Timeline: ${esc(i.timeline)}<br>Reference: ${esc(i.reference||'None')}</p></div>`)}
if(b.matches('[data-category-delete]')){const c=categories[Number(b.dataset.categoryDelete)];if(projects.some(p=>p.category===c))return toast('Reassign projects in this category before deleting it.');modal('<h3>Delete category?</h3><p style="margin:20px 0">'+esc(c)+'</p><button class="button" id="confirm-category-delete">Delete Category</button>');document.querySelector('#confirm-category-delete').onclick=()=>{if(save('categories',categories.filter(x=>x!==c)))location.reload()}}
if(b.matches('[data-category-edit]')){const idx=Number(b.dataset.categoryEdit);modal(`<h3>Rename category</h3><form id="rename-category"><label class="field" style="margin:20px 0">Category name<input name="name" required value="${esc(categories[idx])}"></label><button class="button">Save</button></form>`);document.querySelector('#rename-category').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name||categories.some((c,i)=>i!==idx&&c.toLowerCase()===name.toLowerCase()))return toast('Choose a unique category name.');const old=categories[idx];categories[idx]=name;if(save('categories',categories)&&save('projects',projects.map(p=>p.category===old?{...p,category:name}:p)))location.reload()}}
if(b.matches('[data-edit-record]'))openEditor(b.dataset.editRecord);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const n=document.querySelector('.navlinks');n?.classList.remove('open');document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false')}});
addEventListener('scroll',()=>{document.querySelector('.header')?.classList.toggle('scrolled',scrollY>20);document.querySelector('.back-top').classList.toggle('visible',scrollY>600)},{passive:true});
document.querySelector('.newsletter')?.addEventListener('submit',e=>{e.preventDefault();const email=new FormData(e.target).get('email');if(save('subscribers',[...new Set([...read('subscribers'),email])])){toast('Demo subscription saved in this browser.');e.target.reset()}});
document.querySelector('#inquiry-form')?.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.name=data.name.trim();data.description=data.description.trim();if(data.name.length<2||data.description.length<20)return toast('Add your name and at least 20 characters about the project.');if(save('inquiries',[...read('inquiries'),{...data,id:Date.now(),status:'New',created:new Date().toISOString()}])){activity('New demo inquiry from '+data.name);e.target.reset();document.querySelector('#inquiry-feedback').textContent='Your inquiry was saved in this browser. No email has been sent.';toast('Demo inquiry saved. Thank you!')}});
document.querySelector('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(page==='forgot-password'){save('session',null);toast('Demo session cleared. No reset email was sent.');return}if(save('session',{email:data.email,name:data.name||'Demo Designer'}))location.href='admin-dashboard.html'});
document.querySelector('#project-form')?.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),id=Number(e.target.dataset.id)||Date.now();data.title=data.title.trim();if(!data.title)return toast('Enter a project title.');const p={...data,id,year:Number(data.year)};projects=projects.some(x=>x.id===id)?projects.map(x=>x.id===id?p:x):[...projects,p];if(save('projects',projects)){activity('Saved project '+p.title);location.href='project-management.html'}});
document.querySelector('#category-form')?.addEventListener('submit',e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name||categories.some(c=>c.toLowerCase()===name.toLowerCase()))return toast('Enter a unique category.');if(save('categories',[...categories,name]))location.reload()});
document.querySelector('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.available=!!data.available;if(save('profile',data))toast('Profile saved in this browser.')});
document.querySelector('#settings-form')?.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(save('contrast',data.contrast)&&save('social',data.social)){document.body.classList.toggle('high-contrast',data.contrast==='high');toast('Website preferences saved.')}});
document.querySelector('#admin-search')?.addEventListener('input',e=>document.querySelectorAll('[data-row]').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
function openEditor(keyId){const [key,id]=keyId.split(':'),isBlog=key==='blog',list=isBlog?articles():testimonials(),item=list.find(x=>x.id===Number(id))||{};const fields=isBlog?['title','category','date','excerpt']:['name','role','quote'];const d=modal(`<h3>${id==='new'?'Add':'Edit'} ${isBlog?'article':'testimonial'}</h3><form id="record-form" class="form-grid" style="margin-top:20px">${fields.map(f=>`<label class="field full">${f[0].toUpperCase()+f.slice(1)}${['quote','excerpt'].includes(f)?`<textarea name="${f}" required>${esc(item[f]||'')}</textarea>`:`<input name="${f}" type="${f==='date'?'date':'text'}" required value="${esc(item[f]||'')}">`}</label>`).join('')}${isBlog?`<label class="field full">Artwork<select name="image">${seedProjects.map(p=>`<option value="${p.image}" ${p.image===item.image?'selected':''}>${p.title}</option>`).join('')}</select></label>`:''}<div class="full"><button class="button">Save ${isBlog?'Article':'Testimonial'}</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();const data={...Object.fromEntries(new FormData(e.target)),id:item.id||Date.now()};if(save(key,item.id?list.map(x=>x.id===item.id?data:x):[...list,data])){activity('Saved '+key+' record');location.reload()}}}

// Portfolio search, combined category/year filters, sorting and pagination.
if(page==='portfolio'){let category='All',current=1;const search=document.querySelector('#search'),year=document.querySelector('#year'),sort=document.querySelector('#sort'),select=document.querySelector('#category');function update(){let list=published().filter(p=>(category==='All'||(category==='Favorites'?read('favorites').includes(p.id):p.category===category))&&(year.value==='All'||String(p.year)===year.value)&&(p.title+' '+p.category+' '+p.description).toLowerCase().includes(search.value.toLowerCase().trim()));list.sort((a,b)=>sort.value==='name'?a.title.localeCompare(b.title):sort.value==='oldest'?a.year-b.year:b.year-a.year);const pages=Math.ceil(list.length/4);current=Math.max(1,Math.min(current,pages));document.querySelector('#results').textContent=`${list.length} project${list.length===1?'':'s'} · Page ${current} of ${pages||1}`;document.querySelector('#project-results').innerHTML=list.slice((current-1)*4,current*4).map(card).join('')||'<p class="empty">No projects found. Try another filter or reset your search.</p>';document.querySelector('#pagination').innerHTML=Array.from({length:pages},(_,i)=>`<button class="${i+1===current?'active':''}" data-pagenum="${i+1}" ${i+1===current?'aria-current="page"':''}>${i+1}</button>`).join('');document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category))}document.querySelector('#portfolio-filters').onclick=e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;select.value=category==='Favorites'?'All':category;current=1;update()}};[search,year,sort].forEach(el=>el.addEventListener(el===search?'input':'change',()=>{current=1;update()}));select.onchange=()=>{category=select.value;current=1;update()};document.querySelector('#reset').onclick=()=>{search.value='';year.value='All';sort.value='newest';select.value='All';category='All';current=1;update()};document.querySelector('#pagination').onclick=e=>{if(e.target.dataset.pagenum){current=Number(e.target.dataset.pagenum);update();document.querySelector('#portfolio-filters').scrollIntoView()}};update()}
if(page==='blog'){let current=1;function update(){const search=document.querySelector('#blog-search').value.toLowerCase(),category=document.querySelector('#blog-category').value,list=articles().filter(a=>(category==='All'||a.category===category)&&(a.title+' '+a.excerpt).toLowerCase().includes(search));document.querySelector('#featured-article').innerHTML=!search&&category==='All'&&list[0]?`<div class="split" style="margin:35px 0 50px"><a href="blog-details.html?id=${list[0].id}"><img src="${safeImage(list[0].image)}" alt="Featured article artwork"></a><div><div class="eyebrow">FEATURED ARTICLE</div><h2>${esc(list[0].title)}</h2><p>${esc(list[0].excerpt)}</p>${link('blog-details.html?id='+list[0].id,'Read the Story')}</div></div>`:'';const pages=Math.ceil(list.length/3);current=Math.max(1,Math.min(current,pages));document.querySelector('#blog-results-count').textContent=list.length+' articles';document.querySelector('#blog-results').innerHTML=list.slice((current-1)*3,current*3).map(articleCard).join('')||'<p class="empty">No articles found.</p>';document.querySelector('#blog-pagination').innerHTML=Array.from({length:pages},(_,i)=>`<button data-blog-page="${i+1}" class="${i+1===current?'active':''}">${i+1}</button>`).join('')}document.querySelector('#blog-search').oninput=()=>{current=1;update()};document.querySelector('#blog-category').onchange=()=>{current=1;update()};document.querySelector('#blog-pagination').onclick=e=>{if(e.target.dataset.blogPage){current=Number(e.target.dataset.blogPage);update()}};update()}
let quoteIndex=0;function showQuote(){const list=testimonials(),t=list[quoteIndex%list.length];const el=document.querySelector('#quote-content');if(el)el.innerHTML=t?`<span class="accent">★★★★★</span><blockquote>“${esc(t.quote)}”</blockquote><cite>${esc(t.name)}</cite><p>${esc(t.role)}</p>`:'<p>No testimonials yet.</p>'}showQuote();document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{const n=testimonials().length;if(!n)return;quoteIndex=(quoteIndex+Number(b.dataset.slide)+n)%n;showQuote()});
let galleryIndex=0;const galleryImages=[...document.querySelectorAll('.gallery-open')].map(b=>b.dataset.image);function showGallery(){modal(`<img src="${galleryImages[galleryIndex]}" alt="Project gallery image ${galleryIndex+1}"><div class="slider-controls"><button class="icon-button" id="gallery-prev" aria-label="Previous image">←</button><span>${galleryIndex+1} / ${galleryImages.length}</span><button class="icon-button" id="gallery-next" aria-label="Next image">→</button></div>`);document.querySelector('#gallery-prev').onclick=()=>changeGallery(-1);document.querySelector('#gallery-next').onclick=()=>changeGallery(1)}function changeGallery(delta){galleryIndex=(galleryIndex+delta+galleryImages.length)%galleryImages.length;document.querySelector('#modal').close();showGallery()}document.querySelectorAll('.gallery-open').forEach((b,i)=>b.onclick=()=>{galleryIndex=i;showGallery()});document.addEventListener('keydown',e=>{if(document.querySelector('#modal').open&&document.querySelector('#gallery-next')){if(e.key==='ArrowRight')changeGallery(1);if(e.key==='ArrowLeft')changeGallery(-1)}});
